INSERT INTO feature VALUES('visibility','modules','Private by default, exported by `pub`','imports','implemented','ordinary',NULL,'A declaration is private to its source unless a `pub` mark stands before it: an importer reads only the exported names, constructors and members of an exported declaration among them, a private name neither resolves nor clashes there and is refused as private by name, and the editor offers to import only an exported name.','surface-lowering surface-grammar surface-format surface-lsp','corpus/ledger/syntax/pub-declaration.gandr crates/surface-lowering/tests/namespace.rs','corpus/ledger/syntax/pub-declaration.gandr',NULL);
